function check(bool $v,string $message='Assertion failed'):void{if(!$v)throw new RuntimeException($message);}
function fails(string $code,callable $f):void{try{$f();}catch(BookingError $e){check($e->errorCode===$code,'Expected '.$code.', got '.$e->errorCode);return;}throw new RuntimeException('Expected error '.$code);}
function run_case(string $id,string $function,string $title,string $input,string $expected,callable $fn):void{
    global $db,$results,$clock,$catalog;
    $clock=new DateTimeImmutable("2030-11-10 17:30:00");
    $db->exec('DELETE FROM DatBan');$db->exec("UPDATE Ban SET trangThai='TRONG'");$db->exec("UPDATE ChiNhanh SET trangThai='HOAT_DONG'");
    try{$fn();$status='PASS';$actual='Đạt các assertion về kết quả và dữ liệu lưu trong MySQL.';}catch(Throwable $e){$status='FAIL';$actual=$e->getMessage();}
    $meta=$catalog[$id]??throw new RuntimeException('Test ID missing from catalog: '.$id);
    $function=$meta['function'];$title=$meta['title'];$input=$meta['input'];$expected=$meta['expected'];
    $results[]=compact('id','function','title','input','expected','status','actual');echo "$status $id $title\n";
}
